using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using StudentHub.Constants;
namespace StudentHub.Data;
public static class DatabaseInitializer { public static async Task InitializeAsync(IServiceProvider services) { using var scope=services.CreateScope(); var db=scope.ServiceProvider.GetRequiredService<StudentHubDbContext>(); await db.Database.EnsureCreatedAsync(); await db.Database.ExecuteSqlRawAsync("IF OBJECT_ID('Exams','U') IS NULL CREATE TABLE Exams (Id int IDENTITY PRIMARY KEY, OwnerId nvarchar(450) NOT NULL, CourseId int NOT NULL, ExamType nvarchar(32) NOT NULL, StartsAtUtc datetime2 NOT NULL, Location nvarchar(200) NULL, DurationMinutes int NULL, Notes nvarchar(max) NULL, IsCompleted bit NOT NULL);"); await db.Database.ExecuteSqlRawAsync("IF OBJECT_ID('CourseGrades','U') IS NULL CREATE TABLE CourseGrades (Id int IDENTITY PRIMARY KEY, OwnerId nvarchar(450) NOT NULL, CourseId int NOT NULL, Letter nvarchar(12) NOT NULL, GradePoint decimal(5,2) NOT NULL, IsConfirmed bit NOT NULL);"); await db.Database.ExecuteSqlRawAsync("IF OBJECT_ID('Notifications','U') IS NULL CREATE TABLE Notifications (Id int IDENTITY PRIMARY KEY, OwnerId nvarchar(450) NOT NULL, Title nvarchar(180) NOT NULL, Message nvarchar(max) NOT NULL, Category nvarchar(40) NOT NULL, Priority nvarchar(20) NOT NULL, IsRead bit NOT NULL, TargetUrl nvarchar(500) NULL, CreatedAtUtc datetime2 NOT NULL);"); await db.Database.ExecuteSqlRawAsync("IF OBJECT_ID('UserPreferences','U') IS NULL CREATE TABLE UserPreferences (Id int IDENTITY PRIMARY KEY, OwnerId nvarchar(450) NOT NULL, Language nvarchar(10) NOT NULL, Theme nvarchar(20) NOT NULL, AssignmentReminders bit NOT NULL, ExamReminders bit NOT NULL, CalendarReminders bit NOT NULL, AcademicUpdates bit NOT NULL);"); var roles=scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>(); foreach(var role in new[]{StudentHubRoles.Admin,StudentHubRoles.Student}) if(!await roles.RoleExistsAsync(role)) await roles.CreateAsync(new IdentityRole(role)); } }
